SELECT 'consultation_history' AS table_name, count(*)::int AS rows, md5(COALESCE(string_agg(row_to_json(t)::text, '' ORDER BY row_to_json(t)::text), '')) AS fingerprint FROM public.consultation_history t UNION ALL SELECT 'consultations' AS table_name, count(*)::int AS rows, md5(COALESCE(string_agg(row_to_json(t)::text, '' ORDER BY row_to_json(t)::text), '')) AS fingerprint FROM public.consultations t UNION ALL SELECT 'news_posts' AS table_name, count(*)::int AS rows, md5(COALESCE(string_agg(row_to_json(t)::text, '' ORDER BY row_to_json(t)::text), '')) AS fingerprint FROM public.news_posts t UNION ALL SELECT 'page_visits' AS table_name, count(*)::int AS rows, md5(COALESCE(string_agg(row_to_json(t)::text, '' ORDER BY row_to_json(t)::text), '')) AS fingerprint FROM public.page_visits t UNION ALL SELECT 'resource_categories' AS table_name, count(*)::int AS rows, md5(COALESCE(string_agg(row_to_json(t)::text, '' ORDER BY row_to_json(t)::text), '')) AS fingerprint FROM public.resource_categories t UNION ALL SELECT 'resource_files' AS table_name, count(*)::int AS rows, md5(COALESCE(string_agg(row_to_json(t)::text, '' ORDER BY row_to_json(t)::text), '')) AS fingerprint FROM public.resource_files t UNION ALL SELECT 'site_contents' AS table_name, count(*)::int AS rows, md5(COALESCE(string_agg(row_to_json(t)::text, '' ORDER BY row_to_json(t)::text), '')) AS fingerprint FROM public.site_contents t ORDER BY table_name;